<script>
  import { goto } from '$app/navigation';

  let { isMobile } = $props();
  console.log(isMobile)

  let defaultText = 'welcome to me'
  let text = defaultText;

  let defaultRingId = -1;
	let currentRingId = defaultRingId;
  let sliceIdx = 5;

  let ringHoverStrokeWidth = 6.0;
  let ringHoverOpacity = 0.2;
	
	function onEnter(e) {
    let newId = parseTreeId(e.target.id);
    if (currentRingId === defaultRingId) {
      currentRingId = newId;
      switch (newId) {
        case 26:
          text = 'about me'
          break;
        case 25:
          text = 'my projects'
          break;
        case 24: 
          text = 'my keepsakses'
          break;
        default:
          text = 'work in progress...';
          break;
      }
    } else if (newId < currentRingId) {
      currentRingId = defaultRingId;
      text = defaultText;
    }
	}
  function onLeave(e) {		
    let id = parseTreeId(e.target.id);
    if (currentRingId === id) {
      currentRingId = defaultRingId;
      text = defaultText;
    }
	}	

  function handleClick(e) {
    let id = parseTreeId(e.target.id);
    switch (id) {
      case 26:
        goto('/about');
        break;
      case 25:
        goto('/projects')
        break;
      case 24:
        goto('/keepsakes')
        break;
    }
  }

  function parseTreeId(id) {
    return parseInt(id.slice(sliceIdx))
  }
</script>

<div>
{#if !isMobile }
  <div class="font-sans m-1 mb-2">
    <div class="flex justify-center">
      <div class="m-1">
        <p>{@html text}</p>
      </div>
    </div>
  </div>
{/if}

